    private void BMeterActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BMeterActionPerformed
        if(canicas.size() < 10){
            canicas.push(esfera);
        mostrarFila();
        }
        
    }//GEN-LAST:event_BMeterActionPerformed

    private void BSacarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BSacarActionPerformed
        if (canicas.size() > 0) {
            canicas.pop();
            mostrarFila();
        } else {
            JOptionPane.showMessageDialog(this, "No hay canicas en la fila");
        }
    }//GEN-LAST:event_BSacarActionPerformed

    private void BVaciarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BVaciarActionPerformed
        canicas.clear();
        mostrarFila();
    }//GEN-LAST:event_BVaciarActionPerformed

